var predictionCache = newPredictionCache()

func file*(n: Node): Node = n.son(lbFile)
func at*(n: Node): Node = n.son(lbAt)
func virtual*(n: Node): Node = n.son(lbVirtual)
func banked*(n: Node): Node = n.son(lbBanked)
func selfmod*(n: Node): Node = n.son(lbSelfmod)
func `type`*(n: Node): Node = n.son(lbType)
func name*(n: Node): Node = n.son(lbName)
func noreturn*(n: Node): Node = n.son(lbNoreturn)
func exportFile*(n: Node): Node = n.son(lbExportFile)
func open*(n: Node): Node = n.son(lbOpen)
func start*(n: Node): Node = n.son(lbStart)
func `end`*(n: Node): Node = n.son(lbEnd)
func terminator*(n: Node): Node = n.son(lbTerminator)
func op*(n: Node): seq[Node] = n.sonsWith(lbOp)

proc ruleFile(p: var Parser, returnState: int): Node
proc ruleStatement(p: var Parser, returnState: int): Node
proc ruleAnnotation(p: var Parser, returnState: int): Node
proc rulePlace(p: var Parser, returnState: int): Node
proc ruleNumber(p: var Parser, returnState: int): Node
proc ruleDataType(p: var Parser, returnState: int): Node
proc ruleTypeName(p: var Parser, returnState: int): Node
proc ruleSize(p: var Parser, returnState: int): Node
proc ruleParameters(p: var Parser, returnState: int): Node
proc ruleParameter(p: var Parser, returnState: int): Node

proc ruleFile(p: var Parser, returnState: int): Node =
  ## `file`, line 8
  result = p.newNode(nkFile)
  p.enter(0, returnState, 0)
  try:
    while p.more(result, {tkDeflower, tkInclude, tkRBrace, tkHEX, tkINT,
        tkCOMMENT, tkNL}, {tkEOF}):
      result.add(ruleStatement(p, 0))
    p.match(result, tkEOF)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleStatement(p: var Parser, returnState: int): Node =
  ## `statement`, line 9
  p.enter(1, returnState, 0)
  try:
    case p.peek
    of tkCOMMENT, tkNL:
      result = p.newNode(nkBlank)
      if p.peek in {tkCOMMENT}:
        p.match(result, tkCOMMENT)
      else:
        p.expect({tkCOMMENT})
      p.match(result, tkNL)
    of tkDeflower:
      result = p.newNode(nkDeflower)
      p.match(result, tkDeflower)
      p.match(result, tkID, lbFile)
      p.match(result, tkNL)
    of tkInclude:
      result = p.newNode(nkInclude)
      p.match(result, tkInclude)
      p.match(result, tkID, lbFile)
      p.match(result, tkNL)
    of tkRBrace:
      result = p.newNode(nkEndBlock)
      p.match(result, tkRBrace)
      p.match(result, tkNL)
    of tkHEX, tkINT:
      result = p.newNode(nkLine)
      result.add(ruleAnnotation(p, 23))
      p.match(result, tkNL)
    else:
      p.fail({tkDeflower, tkInclude, tkRBrace, tkHEX, tkINT, tkCOMMENT, tkNL})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleAnnotation(p: var Parser, returnState: int): Node =
  ## `annotation`, line 15
  result = p.newNode(nkAnnotation)
  p.enter(2, returnState, 0)
  try:
    result.add(rulePlace(p, 26), lbAt)
    if p.peek in {tkVirtual}:
      p.match(result, tkVirtual, lbVirtual)
    else:
      p.expect({tkVirtual})
    if p.peek in {tkBanked}:
      p.match(result, tkBanked, lbBanked)
    else:
      p.expect({tkBanked})
    if p.peek in {tkSelfmod}:
      p.match(result, tkSelfmod, lbSelfmod)
    else:
      p.expect({tkSelfmod})
    if p.peek in {tkScreencode, tkAscii, tkByte, tkWord, tkLong, tkDword,
        tkAddr, tkRta, tkSbyte, tkSword, tkSlong, tkSdword, tkCode}:
      result.add(ruleDataType(p, 33), lbType)
    else:
      p.expect({tkScreencode, tkAscii, tkByte, tkWord, tkLong, tkDword, tkAddr,
          tkRta, tkSbyte, tkSword, tkSlong, tkSdword, tkCode})
    if p.peek in {tkID}:
      p.match(result, tkID, lbName)
    else:
      p.expect({tkID})
    if p.peek in {tkLParen}:
      result.add(ruleParameters(p, 37))
    else:
      p.expect({tkLParen})
    if p.peek in {tkNoreturn}:
      p.match(result, tkNoreturn, lbNoreturn)
    else:
      p.expect({tkNoreturn})
    if p.peek in {tkExport}:
      p.match(result, tkExport)
      p.match(result, tkID, lbExportFile)
    else:
      p.expect({tkExport})
    if p.peek in {tkLBrace}:
      p.match(result, tkLBrace, lbOpen)
    else:
      p.expect({tkLBrace})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc rulePlace(p: var Parser, returnState: int): Node =
  ## `place`, line 18
  result = p.newNode(nkPlace)
  p.enter(3, returnState, 0)
  try:
    result.add(ruleNumber(p, 47), lbStart)
    if p.peek in {tkMinus}:
      p.match(result, tkMinus)
      result.add(ruleNumber(p, 46), lbEnd)
    else:
      p.expect({tkMinus})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleNumber(p: var Parser, returnState: int): Node =
  ## `number`, line 19
  result = p.newNode(nkNumber)
  p.enter(4, returnState, 0)
  try:
    case p.peek
    of tkINT:
      p.match(result, tkINT)
    of tkHEX:
      p.match(result, tkHEX)
    else:
      p.fail({tkHEX, tkINT})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleDataType(p: var Parser, returnState: int): Node =
  ## `dataType`, line 20
  result = p.newNode(nkDataType)
  p.enter(5, returnState, 0)
  try:
    result.add(ruleTypeName(p, 58))
    if p.peek in {tkLBracket}:
      p.match(result, tkLBracket)
      if p.peek in {tkUntil, tkLengthbyte, tkHEX, tkINT}:
        result.add(ruleSize(p, 61))
      else:
        p.expect({tkUntil, tkLengthbyte, tkHEX, tkINT})
      p.match(result, tkRBracket)
    else:
      p.expect({tkLBracket})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleTypeName(p: var Parser, returnState: int): Node =
  ## `typeName`, line 21
  result = p.newNode(nkTypeName)
  p.enter(6, returnState, 0)
  try:
    case p.peek
    of tkScreencode:
      p.match(result, tkScreencode)
    of tkAscii:
      p.match(result, tkAscii)
    of tkByte:
      p.match(result, tkByte)
    of tkWord:
      p.match(result, tkWord)
    of tkLong:
      p.match(result, tkLong)
    of tkDword:
      p.match(result, tkDword)
    of tkAddr:
      p.match(result, tkAddr)
    of tkRta:
      p.match(result, tkRta)
    of tkSbyte:
      p.match(result, tkSbyte)
    of tkSword:
      p.match(result, tkSword)
    of tkSlong:
      p.match(result, tkSlong)
    of tkSdword:
      p.match(result, tkSdword)
    of tkCode:
      p.match(result, tkCode)
    else:
      p.fail({tkScreencode, tkAscii, tkByte, tkWord, tkLong, tkDword, tkAddr,
          tkRta, tkSbyte, tkSword, tkSlong, tkSdword, tkCode})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleSize(p: var Parser, returnState: int): Node =
  ## `size`, line 23
  p.enter(7, returnState, 0)
  try:
    case p.peek
    of tkUntil:
      result = p.newNode(nkUntil)
      p.match(result, tkUntil)
      result.add(ruleNumber(p, 94), lbTerminator)
    of tkLengthbyte:
      result = p.newNode(nkLengthByte)
      p.match(result, tkLengthbyte)
    of tkHEX, tkINT:
      result = p.newNode(nkCount)
      result.add(ruleNumber(p, 100))
      while p.more(result, {tkStar, tkPlus}, {tkRBracket}):
        p.matchSet(result, {tkStar, tkPlus}, lbOp)
        result.add(ruleNumber(p, 100))
    else:
      p.fail({tkUntil, tkLengthbyte, tkHEX, tkINT})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleParameters(p: var Parser, returnState: int): Node =
  ## `parameters`, line 27
  result = p.newNode(nkParameters)
  p.enter(8, returnState, 0)
  try:
    p.match(result, tkLParen)
    result.add(ruleParameter(p, 110))
    while p.more(result, {tkComma}, {tkRParen}):
      p.match(result, tkComma)
      result.add(ruleParameter(p, 110))
    p.match(result, tkRParen)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleParameter(p: var Parser, returnState: int): Node =
  ## `parameter`, line 28
  result = p.newNode(nkParameter)
  p.enter(9, returnState, 0)
  try:
    result.add(ruleDataType(p, 116))
    if p.peek in {tkID}:
      p.match(result, tkID, lbName)
    else:
      p.expect({tkID})
  except SyntaxError:
    p.recover(result)
  p.leave()

const followSets: array[10, set[TokenKind]] = [
  {tkEOF}, # file
  {tkEOF, tkDeflower, tkInclude, tkRBrace, tkHEX, tkINT, tkCOMMENT,
      tkNL}, # statement
  {tkEOF, tkNL}, # annotation
  {tkEOF, tkVirtual, tkBanked, tkSelfmod, tkNoreturn, tkExport, tkLBrace,
      tkScreencode, tkAscii, tkByte, tkWord, tkLong, tkDword, tkAddr, tkRta,
      tkSbyte, tkSword, tkSlong, tkSdword, tkCode, tkLParen, tkID,
      tkNL}, # place
  {tkEOF, tkVirtual, tkBanked, tkSelfmod, tkNoreturn, tkExport, tkLBrace,
      tkMinus, tkRBracket, tkScreencode, tkAscii, tkByte, tkWord, tkLong,
      tkDword, tkAddr, tkRta, tkSbyte, tkSword, tkSlong, tkSdword, tkCode,
      tkStar, tkPlus, tkLParen, tkID, tkNL}, # number
  {tkEOF, tkNoreturn, tkExport, tkLBrace, tkLParen, tkComma, tkRParen, tkID,
      tkNL}, # dataType
  {tkEOF, tkNoreturn, tkExport, tkLBrace, tkLBracket, tkLParen, tkComma,
      tkRParen, tkID, tkNL}, # typeName
  {tkEOF, tkRBracket}, # size
  {tkEOF, tkNoreturn, tkExport, tkLBrace, tkNL}, # parameters
  {tkEOF, tkComma, tkRParen}] # parameter

const ruleNames = ["file", "statement", "annotation", "place", "number",
    "dataType", "typeName", "size", "parameters", "parameter"]

proc follows(rule, kind: int): bool = TokenKind(kind) in followSets[rule]

func foundKind*(e: SyntaxErrorInfo): TokenKind =
  ## The kind of the token a syntax error found, if `e.hasToken`.
  TokenKind(e.found)

func expectedKinds*(e: SyntaxErrorInfo): seq[TokenKind] =
  ## The kinds of the tokens that could have come where a syntax error is.
  for k in e.expected: result.add TokenKind(k)

proc parseWith(src, filename: string, formatter: SyntaxErrorFormatter,
    rule: proc (p: var Parser): Node {.nimcall.}): ParseResult[Node] =
  result.diagnostics.filename = filename
  let tokens = tokenize(src, result.diagnostics)
  result.tree = runParser[NodeKind, NodeLabel, TokenKind](tokens, src,
    result.diagnostics, @ruleNames, follows, rule)
  result.diagnostics.formatSyntaxErrors(formatter)

proc parseFile*(src: string, filename = "input",
    formatter: SyntaxErrorFormatter = nil): ParseResult[Node] =
  ## Parses `src` with rule `file`. A `formatter` words the
  ## syntax errors instead of the default messages.
  parseWith(src, filename, formatter, proc (p: var Parser): Node =
    ruleFile(p, -1))

